import {LayoutDashboard,CalendarDays,ClipboardCheck,Users,CheckCheck,BarChart3,Bell,Settings,ShieldCheck,Leaf,LogOut,Sun,Moon,Search,Plus,Download,Clock,MapPin,HeartHandshake,BookOpen,Camera,ChevronRight,ChevronLeft,Check,TriangleAlert,FileText,History,UserRound,Menu,ArrowUpRight,Activity,Building2,GraduationCap,CheckCircle2,Inbox,LoaderCircle,RefreshCw,Mail,LockKeyhole,Upload,ExternalLink,TreePine,Heart,ChevronDown,SlidersHorizontal} from 'lucide-react';
import {SidebarProvider,Sidebar,SidebarContent,SidebarFooter,SidebarHeader,SidebarTrigger} from '@/components/ui/sidebar';
