 {actionError&&modal&&<div className="error-banner" role="alert">{actionError}</div>}
 {modal&&<ModalBody key={modal.kind+String(modal.record?.id||modal.event?.id||modal.person?.id||'')} modal={modal} data={{...data,evidence:modal.evidence||data.evidence,corrections:modal.corrections||data.corrections}} busy={busy} action={action} run={run} open={open} close={()=>setModal(null)} selected={selected} nav={nav}/>}
