 if(m.kind==='import')return <div className="form-stack"><p>Upload a CSV with these exact column headings. Up to 200 students per import. Duplicate emails or NSS IDs reject the whole import.</p><code className="info-strip">name,email,department,batch,year,nss_id,roll</code><Button onClick={()=>{const csv='name,email,department,batch,year,nss_id,roll\n';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='sevatrack-import-template.csv';a.click();URL.revokeObjectURL(a.href)}}>Download CSV template</Button><Field label="Student CSV" name="csv" type="file" accept=".csv,text/csv" onChange={async(e:any)=>{try{let file=e.target.files?.[0];if(!file)return;if(file.size>200000)throw new Error('CSV must be under 200 KB.');const text=await file.text();const rows=parseCSV(text),head=rows.shift()||[];if(!['name','email','department','batch','year','nss_id','roll'].every(k=>head.includes(k)))throw new Error('CSV headers do not match the template.');const parsed=rows.filter(r=>r.some(Boolean)).map(r=>Object.fromEntries(head.map((k,i)=>[k,r[i]||''])));setImportRows(parsed);setResult(`${parsed.length} students ready. First: ${parsed[0]?.name||'—'}`)}catch(e:any){setImportRows([]);setResult(e.message)}}}/>{result&&<div className="info-strip">{result}</div>}<Button kind="primary" disabled={busy||!importRows.length} onClick={()=>run('import',{rows:importRows})}>Import {importRows.length} students</Button></div>;
