function AuditList({rows}:any){return rows.length?<div>{rows.map((a:Row)=>{const before=JSON.parse(a.old_value)||{},after=JSON.parse(a.new_value)||{};return <article key={a.id} className="audit-item"><h3>{a.action}</h3><p>{a.actor_name||a.actor} · {stamp(a.created_at)}</p><p><strong>Reason:</strong> {a.reason}</p>{['effective_in','effective_out','status','hours'].filter(k=>k in after).map(k=><div className="audit-change" key={k}><strong>{title(k)}</strong><span>{k.includes('effective')?stamp(before[k]):String(before[k]??'—')} → {k.includes('effective')?stamp(after[k]):String(after[k]??'—')}</span></div>)}<details><summary>Complete record</summary><pre>Before: {readableAudit(a.old_value)}{'\n'}After: {readableAudit(a.new_value)}</pre></details></article>})}</div>:<Blank title="No adjustments yet">Changes to this attendance record will appear here.</Blank>}
function readableAudit(value:string){try{const v=JSON.parse(value);if(!v)return '—';return Object.entries(v).filter(([k])=>!['password','location_in','location_out'].includes(k)).map(([k,x])=>`${title(k)}: ${typeof x==='object'?JSON.stringify(x):x??'—'}`).join('\n')}catch{return value}}
function parseCSV(text:string){const rows:string[][]=[];let row:string[]=[],cell='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote;}else if(c===','&&!quote){row.push(cell.trim());cell='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());rows.push(row);row=[];cell='';}else cell+=c}if(quote)throw new Error('Unclosed CSV quote.');if(cell||row.length){row.push(cell.trim());rows.push(row)}if(rows[0]?.[0])rows[0][0]=rows[0][0].replace(/^\ufeff/,'');return rows;}

function SearchBox({search,setSearch,setPageNumber,label}:any){return <div className="search"><Search size={17}/><input className="input" placeholder={`Search ${label?.toLowerCase()}…`} aria-label="Search records" value={search} onChange={e=>{setSearch(e.target.value);setPageNumber(1)}}/></div>}
function RecordBrowser({kind='attendance',data,open,student=false,initialEvent='',initialStatus='',studentId='',onMark}:any){const [q,setQ]=useState(''),[query,setQuery]=useState(''),[status,setStatus]=useState(initialStatus||(kind==='events'?'upcoming':'all')),[event,setEvent]=useState(initialEvent),[sort,setSort]=useState('date'),[dir,setDir]=useState(kind==='events'?'asc':'desc'),[page,setPage]=useState(1),[size,setSize]=useState('25'),[result,setResult]=useState<Row>({rows:[],total:0,pages:1,page:1,size:25}),[loading,setLoading]=useState(true),[error,setError]=useState(''),[checked,setChecked]=useState<Row[]>([]),[retry,setRetry]=useState(0);useEffect(()=>{const t=setTimeout(()=>{setQuery(q);setPage(1)},250);return()=>clearTimeout(t)},[q]);useEffect(()=>{const c=new AbortController();setLoading(true);setError('');const p=new URLSearchParams({kind,q:query,status,event,sort,dir,page:String(page),size,student:studentId});fetch('/api/records?'+p,{signal:c.signal,cache:'no-store'}).then(async r=>{const d:any=await r.json();if(!r.ok)throw new Error(d.error||'Unable to load records.');return d}).then(d=>setResult(d)).catch(e=>{if(e.name!=='AbortError')setError(e.message)}).finally(()=>{if(!c.signal.aborted)setLoading(false)});return()=>c.abort()},[kind,query,status,event,sort,dir,page,size,data.fetchedAt,retry,studentId]);
 const change=(fn:any)=>(v:string)=>{fn(v);setPage(1);setChecked([])};const rows=result.rows;const toggle=(a:Row,value:any)=>{setChecked(prev=>{if(!value)return prev.filter(x=>x.id!==a.id);if(prev.length>=50){toast.error('Select up to 50 students per bulk action.');return prev}return prev.some(x=>x.id===a.id)?prev:[...prev,a]})};const allPage=rows.length>0&&rows.every((a:Row)=>checked.some(x=>x.id===a.id));
 return <div className="records-workspace"><div className="toolbar"><div className="search"><Search size={17}/><input className="input" value={q} onChange={e=>setQ(e.target.value)} aria-label="Search records" placeholder={kind==='attendance'?'Search name, NSS ID, roll number or event…':'Search '+kind+'…'}/></div>{kind==='attendance'&&<><Choice label="Attendance status" value={status} onChange={change(setStatus)} options={[{value:'all',label:'All statuses'},{value:'pending',label:'Needs review'},'REGISTERED','CHECKED_IN','EVIDENCE_PENDING','PENDING_REVIEW','APPROVED','PARTIAL','ABSENT','REJECTED','CANCELLED']}/><Choice label="Filter by event" value={event||'all'} onChange={(v:string)=>change(setEvent)(v==='all'?'':v)} options={[{value:'all',label:'All events'},...data.events.map((e:Row)=>({value:e.id,label:e.title+' · '+dates(e.start)}))]}/></>}{kind==='notifications'&&<Choice label="Notification status" value={status} onChange={change(setStatus)} options={[{value:'all',label:'All updates'},{value:'unread',label:'Unread only'}]}/>} {kind==='events'&&<Tabs value={status} onValueChange={change(setStatus)}><TabsList><TabsTrigger value="upcoming">Upcoming</TabsTrigger><TabsTrigger value="past">Past</TabsTrigger>{!student&&<TabsTrigger value="draft">Drafts</TabsTrigger>}</TabsList></Tabs>}<Choice label="Sort records" value={sort+':'+dir} onChange={(v:string)=>{const [s,d]=v.split(':');setSort(s);setDir(d);setPage(1)}} options={[{value:'date:desc',label:'Newest first'},{value:'date:asc',label:'Oldest first'},{value:'name:asc',label:kind==='attendance'?'Student A–Z':'Name A–Z'},...(kind==='attendance'?[{value:'hours:desc',label:'Most hours'}]:[])]}/>{kind==='attendance'&&!student&&<Button onClick={()=>open('manual')}><Plus size={16}/>Add participant</Button>}{['attendance','history'].includes(kind)&&<a className="btn" href={'/api/export?type='+(kind==='history'?'history':'attendance')+(event?'&event='+encodeURIComponent(event):'')}><Download size={16}/>Export CSV</a>}</div>
 {checked.length>0&&<div className="selection-bar"><strong>{checked.length} selected</strong><span>Selections are kept across pages · maximum 50 per action</span><Button kind="small" onClick={()=>setChecked([])}>Clear selection</Button><Button kind="primary small" onClick={()=>open('bulk',{records:checked})}>Review selected</Button></div>}
 {error?<div className="panel empty" role="alert"><TriangleAlert/><h3>Records couldn’t load</h3><p>{error}</p><Button onClick={()=>setRetry(retry+1)} className="mt-4"><RefreshCw size={16}/>Try again</Button></div>:loading?<div className="panel p-5" aria-busy="true" aria-label="Loading records">{[0,1,2,3,4].map(i=><Skeleton key={i} className="h-14 mb-3"/>)}</div>:!rows.length?<div className="panel"><Blank title={query||status!=='all'?'No matching records':'Nothing here yet'}>{kind==='events'?'New activities will appear when your coordinator publishes them.':'Try a different filter or search. Records appear here as your NSS program gets started.'}</Blank></div>:kind==='notifications'?<div className="panel">{rows.map((n:Row)=><div className={'notification '+(!n.read?'unread':'')} key={n.id}><span className="review-icon"><Bell size={18}/></span><div style={{flex:1}}><h3>{n.title} {!n.read&&<span className="pill">Unread</span>}</h3><p>{n.body}</p><small>{stamp(n.created_at)}</small></div>{!n.read&&<Button kind="small" onClick={()=>onMark(n.id)}>Mark read</Button>}</div>)}</div>:['evidence','corrections'].includes(kind)?<div className="panel">{rows.map((p:Row)=><div className="review-item" key={p.id}><span className="review-icon">{kind==='evidence'?<Camera size={20}/>:<History size={20}/>}</span><div style={{flex:1,minWidth:0}}><h3>{p.student_name}</h3><p>{p.event_title} · {stamp(p.created_at)}</p>{kind==='evidence'?<Badge status={JSON.parse(p.location).status}/>:<p>{p.issue}: {p.explanation}</p>}</div><Button kind="small" onClick={()=>kind==='evidence'?open('proof-review',{proof:p}):open('review',{record:{id:p.attendance_id},correction:p})}>{kind==='evidence'?'Review photo':'Resolve'}</Button></div>)}</div>:kind==='events'?<div className="events-grid">{rows.map((e:Row)=><button className="event-card" key={e.id} onClick={()=>open('event-detail',{event:e})}><div className={'event-visual '+(e.category==='Education'?'blue':'')} style={e.banner?{backgroundImage:`url(${e.banner})`}:undefined}><div className="date-stamp"><b>{new Date(e.start).getDate()}</b><small>{dates(e.start,{month:'short'}).toUpperCase()}</small></div><CalendarDays size={46} className="event-symbol"/></div><div className="event-info"><Badge status={e.status}/><h3>{e.title}</h3><div className="event-meta"><MapPin size={14}/>{e.location}</div><div className="event-meta"><Clock size={14}/>{time(e.start)} – {time(e.end)}</div></div><div className="event-bottom"><span>{e.registrations} / {e.capacity} volunteers</span><span className="pill green">{fmt(e.hours)} service hrs</span></div></button>)}</div>:<div className="panel"><div className="table-wrap" tabIndex={0} aria-label="Scrollable records table"><Table><TableHeader><TableRow>{kind==='attendance'?<>{!student&&<TableHead><Checkbox aria-label="Select this page" checked={allPage} onCheckedChange={v=>setChecked(prev=>v?[...prev,...rows.filter((a:Row)=>!prev.some(x=>x.id===a.id))].slice(0,50):prev.filter(x=>!rows.some((a:Row)=>a.id===x.id)))}/></TableHead>}<TableHead>{student?'Activity':'Volunteer'}</TableHead>{!student&&<TableHead>Event</TableHead>}<TableHead>Effective times</TableHead><TableHead>Duration</TableHead><TableHead>Location / proof</TableHead><TableHead>Status</TableHead><TableHead>Hours</TableHead><TableHead>Actions</TableHead></>:kind==='history'?['Activity','Date','Year','Hours','Reason','Recorded by'].map(h=><TableHead key={h}>{h}</TableHead>):kind==='reports'?['Event','Date','Registered','Approved','Absent','Service hours','Export'].map(h=><TableHead key={h}>{h}</TableHead>):['When','Actor','Action','Reason','Details'].map(h=><TableHead key={h}>{h}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.map((a:Row)=><TableRow key={a.id}>{kind==='attendance'?<>{!student&&<TableCell><Checkbox aria-label={'Select '+a.student_name} checked={checked.some(x=>x.id===a.id)} onCheckedChange={v=>toggle(a,v)}/></TableCell>}<TableCell>{student?<strong>{a.event_title}</strong>:<Person name={a.student_name} sub={a.nss_id}/>}</TableCell>{!student&&<TableCell>{a.event_title}</TableCell>}<TableCell><div>{time(a.effective_in)}</div><small className="muted">{time(a.effective_out)}</small>{(a.original_in!==a.effective_in||a.original_out!==a.effective_out)&&<small className="adjusted-label">Faculty adjusted</small>}</TableCell><TableCell>{duration(a)}</TableCell><TableCell><div className="flex flex-col items-start gap-2">{a.location_in?<Badge status={JSON.parse(a.location_in).status}/>:<span className="muted">No location yet</span>}{a.proof_count>0?<button className="text-btn" onClick={()=>open('proof-for-attendance',{record:a})}><Camera size={14} className="inline mr-1"/>{a.proof_count} photo{a.proof_count===1?'':'s'}{a.pending_proof?' · needs review':''}</button>:<span className="muted">{a.proof_required?'Photo required':'Photo optional'}</span>}</div></TableCell><TableCell><Badge status={a.status}/></TableCell><TableCell><strong>{fmt(a.approved_hours)}h</strong></TableCell><TableCell><Button kind="small" onClick={()=>open(student?'attendance-detail':'review',{record:a})}>{student?'View':'Review'}</Button></TableCell></>:kind==='history'?<><TableCell>{a.event_title}</TableCell><TableCell>{stamp(a.created_at)}</TableCell><TableCell>Year {a.year}</TableCell><TableCell><strong className="history-amount">{a.delta>=0?'+':''}{fmt(a.delta)}</strong></TableCell><TableCell>{a.reason}</TableCell><TableCell>{a.actor_name||'Coordinator'}</TableCell></>:kind==='reports'?<><TableCell>{a.title}</TableCell><TableCell>{dates(a.start)}</TableCell><TableCell>{a.registrations}</TableCell><TableCell>{a.approved}</TableCell><TableCell>{a.absent}</TableCell><TableCell>{fmt(a.hours)}</TableCell><TableCell><a className="btn small" href={'/api/export?event='+a.id}>CSV</a></TableCell></>:<><TableCell>{stamp(a.created_at)}</TableCell><TableCell>{a.actor_name||'NSS administrator'}<small className="muted block">{title(a.role)}</small></TableCell><TableCell>{a.action}</TableCell><TableCell>{a.reason}</TableCell><TableCell><Button kind="small" onClick={()=>open('audit-detail',{entry:a})}>Details</Button></TableCell></>}</TableRow>)}</TableBody></Table></div></div>}
 <div className="table-footer no-print"><span aria-live="polite">{result.total?`${(result.page-1)*result.size+1}–${Math.min(result.page*result.size,result.total)}`:'0'} of {result.total} records</span><div className="flex-row wrap"><Choice label="Rows per page" value={size} onChange={change(setSize)} options={[{value:'10',label:'10 per page'},{value:'25',label:'25 per page'},{value:'50',label:'50 per page'}]}/><Button kind="small" disabled={loading||result.page<=1} onClick={()=>setPage(result.page-1)}><ChevronLeft size={16}/>Previous</Button><span>{result.page} / {result.pages}</span><Button kind="small" disabled={loading||result.page>=result.pages} onClick={()=>setPage(result.page+1)}>Next<ChevronRight size={16}/></Button></div></div></div>
}
function StudentOverview({data:d,onOpen,onNavigate}:any){const s=d.students.find((s:Row)=>s.id===d.user.id)||{y1:0,y2:0},p=progress(s.y1,s.y2,d.settings.year1,d.settings.year2);const next=d.next;const recent=d.latest;return <><section className="service-summary" aria-label="Your service progress"><div><span className="eyebrow">YOUR NSS JOURNEY</span><div className="service-number">{fmt(p.total)}<span> / {d.settings.year1+d.settings.year2} hrs</span></div><p>Verified service hours</p></div><div className="remaining"><strong>{fmt(p.remaining)}h</strong><span>remaining across both years</span>{p.extra>0&&<span className="pill green">+{fmt(p.extra)} extra service hours</span>}</div><div className="service-years">{[1,2].map(y=>{const n=y===1?s.y1:s.y2,required=d.settings['year'+y];return <div key={y}><div className="flex-row between"><strong>Year {y}</strong><span>{fmt(n)} / {required}h</span></div><Progress value={Math.min(100,n/required*100)} aria-label={`Year ${y}: ${n} of ${required} hours`}/><small>{n>=required?'Requirement completed':y>d.user.year?'Not started':`${fmt(required-n)} hours remaining`}</small></div>})}</div></section><div className="student-actions"><div className="panel panel-body"><div className="flex-row between"><span className="review-icon"><CalendarDays size={20}/></span><span className="eyebrow">NEXT ACTIVITY</span></div><h3>{next?.event_title||'Find your next opportunity'}</h3><p>{next?`${dates(next.event_start)} · ${next.event_location}`:'Browse activities and register for something meaningful.'}</p><Button kind="primary" onClick={()=>next?onOpen('attendance-detail',{record:next}):onNavigate('events')}>{next?.status==='CHECKED_IN'?'Continue attendance':next?'View attendance':'Explore events'}</Button></div><div className="panel panel-body"><div className="flex-row between"><span className="review-icon blue"><ClipboardCheck size={20}/></span><span className="eyebrow">NEEDS ATTENTION</span></div><h3>{d.counts.pending?`${d.counts.pending} activities awaiting review`:'You’re up to date'}</h3><p>{d.attendance.some((a:Row)=>a.status==='EVIDENCE_PENDING')?'Some activities still need a participation photo.':d.counts.pending?'Your coordinator will verify attendance and award service hours.':'Your attendance and participation updates will appear here.'}</p><Button onClick={()=>onNavigate('attendance')}>View participation</Button></div><div className="panel panel-body"><div className="flex-row between"><span className="review-icon purple"><CheckCircle2 size={20}/></span><span className="eyebrow">LATEST DECISION</span></div><h3>{recent?.event_title||'Your first contribution awaits'}</h3><p>{recent?<><Badge status={recent.status}/> · {fmt(recent.approved_hours)} approved hours</>:'Approved activities become part of your permanent NSS history.'}</p><Button onClick={()=>recent?onOpen('attendance-detail',{record:recent}):onNavigate('history')}>View activity history</Button></div></div></>}

function NetworkStatus(){const [online,setOnline]=useState(true);useEffect(()=>{const update=()=>setOnline(navigator.onLine);update();window.addEventListener('online',update);window.addEventListener('offline',update);return()=>{window.removeEventListener('online',update);window.removeEventListener('offline',update)}},[]);return online?null:<div className="offline-banner" role="alert"><TriangleAlert size={18}/>You’re offline. Reconnect before submitting attendance or saving changes.</div>}
function LocationEvidence({record:a}:any){return <section className="location-evidence" aria-label="Attendance GPS evidence">{['in','out'].map(k=>{const loc=a['location_'+k]?JSON.parse(a['location_'+k]):null;return <div className="info-strip" key={k}><strong>Check-{k} location</strong>{loc?<><div className="mt-2"><Badge status={loc.status}/></div><p>{loc.denied?loc.reason||'GPS unavailable':`${loc.distance} m from event · ±${Math.round(loc.accuracy)} m accuracy`}</p>{!loc.denied&&<a className="text-btn" target="_blank" rel="noreferrer" href={`https://www.openstreetmap.org/?mlat=${loc.lat}&mlon=${loc.lng}#map=17/${loc.lat}/${loc.lng}`}>View recorded location</a>}</>:<p>No location was recorded.</p>}</div>})}</section>}
function GeoDiagram({evidence:p}:any){const loc=JSON.parse(p.location);if(loc.denied||loc.lat===undefined||p.event_lat===undefined)return null;const rad=Math.PI/180,dy=(loc.lat-p.event_lat)*rad*6371000,dx=(loc.lng-p.event_lng)*rad*6371000*Math.cos(p.event_lat*rad),extent=Math.max(p.radius,Math.hypot(dx,dy)+loc.accuracy,50)*1.2,scale=85/extent,x=150+dx*scale,y=105-dy*scale;return <figure className="geo-diagram"><svg viewBox="0 0 300 210" role="img" aria-label={`Submission is ${loc.distance} metres from the event centre. Allowed radius ${p.radius} metres. GPS accuracy ${Math.round(loc.accuracy)} metres.`}><circle className="boundary" cx="150" cy="105" r={p.radius*scale}/><circle className="accuracy" cx={x} cy={y} r={Math.max(3,loc.accuracy*scale)}/><circle className="center" cx="150" cy="105" r="4"/><circle className="point" cx={x} cy={y} r="5"/><text x="10" y="20">Event area · {p.radius} m radius</text><text x="10" y="196">Photo upload location · ±{Math.round(loc.accuracy)} m</text></svg><figcaption>Dashed circle: event boundary. Blue point and circle: reported location and accuracy.</figcaption></figure>}

function DeleteAccountForm({person,busy,run,close}:any){
 const [summary,setSummary]=useState<Row|null>(null),[loadError,setLoadError]=useState(''),[confirmed,setConfirmed]=useState(false),[email,setEmail]=useState(''),[attempt,setAttempt]=useState(0);
 useEffect(()=>{let alive=true;setSummary(null);setLoadError('');request('account-deletion-summary?id='+encodeURIComponent(person.id)).then(v=>{if(alive)setSummary(v)}).catch(e=>{if(alive)setLoadError(e.message)});return()=>{alive=false}},[person.id,attempt]);
 return <form className="form-stack" onSubmit={e=>{const values=formValues(e);if(!summary||!confirmed)return;run('delete-account',{...values,id:person.id})}}>
 <p>This permanently deletes <strong>{person.name}</strong> ({person.email}) and their own attendance, credited hours, corrections, notifications and login access.</p>
 {loadError?<div role="alert" className="info-strip">{loadError}<Button onClick={()=>setAttempt(v=>v+1)}>Retry summary</Button></div>:!summary?<p role="status">Loading deletion summary…</p>:<div className="info-strip"><p>{summary.counts.attendance} attendance records · {summary.counts.photos} submitted photos · {fmt(summary.counts.hours)} credited hours</p><p>{summary.counts.events} managed events will transfer to your admin account. Other students’ records remain; their historical actions show “Deleted account” for this person.</p></div>}
 <p className="help-note">Photo files are queued for permanent removal. Use Retry photo cleanup in Accounts, including a final sweep after 20 minutes. Backups, downloaded exports and mentions in other people’s free-text records are not erased. A deletion receipt and your reason remain in the audit trail; do not include unnecessary personal details.</p>
 <Field label="Type the account email to confirm" name="email" type="email" autoComplete="off" value={email} onChange={(e:any)=>setEmail(e.target.value)}/>
 <Field label="Your administrator password" name="password" type="password" autoComplete="current-password" maxLength={128}/>
 <Field label="Reason for permanent deletion" name="reason" maxLength={1000}/>
 <label className="check-row"><input type="checkbox" required checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>I understand this cannot be undone in SevaTrack.</label>
 <div className="modal-actions"><Button disabled={busy} onClick={close}>Cancel</Button><Button type="submit" kind="primary" disabled={busy||!summary||!confirmed||email.trim().toLowerCase()!==summary.target.email.toLowerCase()}>{busy?'Deleting…':'Permanently delete account'}</Button></div>
 </form>;
}
